//! Frozen outputs are generated by Python, not by the Rust renderer under test.
use agentflow_core::chat::{
    ask, commands, details, forms,
    models::*,
    notices::{self, Notice},
    render, rich,
};
use serde_json::{Value, json};

#[test]
fn python_slack_rendering_and_notice_goldens() {
    let cases: Vec<Value> = serde_json::from_str(include_str!("../../../../contract/golden/chat.json")).unwrap();
    for (index, case) in cases.iter().enumerate() {
        let args = case["args"].as_array().unwrap();
        let string = |i: usize| args[i].as_str().unwrap();
        let result = match case["function"].as_str().unwrap() {
            "task_details" => json!(details::task_details(
                &args[0],
                &serde_json::from_value::<Vec<String>>(args[1].clone()).unwrap(),
                args[2].as_array().map(|_| serde_json::from_value::<Vec<String>>(args[2].clone()).unwrap()).as_deref(),
                args[3].as_u64().unwrap() as usize
            )),
            "render_details" => json!(rich::render_details(&args[0], &args[1], string(2))),
            "render_help" => json!(commands::help(args[0].as_str())),
            "render_ai_answer" => json!(rich::ai_answer(string(0))),
            "render_requirements" => json!(rich::requirements(
                string(0),
                &serde_json::from_value::<Vec<(String, String)>>(args[1].clone()).unwrap()
            )),
            "render_digest" => json!(rich::digest_at(
                args[0].as_array().unwrap(),
                (!args[1].is_null()).then_some(&args[1]),
                chrono::DateTime::parse_from_rfc3339(string(2)).unwrap().with_timezone(&chrono::Utc)
            )),
            "claude_answer" => json!(ask::claude_answer(string(0))),
            "copilot_answer" => json!(ask::copilot_answer(string(0))),
            "build_prompt" => json!(ask::build_prompt(
                &args[0],
                string(1),
                &serde_json::from_value::<Vec<(String, String)>>(args[2].clone()).unwrap()
            )),
            "task_modal" => forms::task_modal(&serde_json::from_value::<TaskForm>(args[0].clone()).unwrap()),
            "answer_modal" => forms::answer_modal(args[0].as_array().unwrap(), &args[1]),
            "text_modal" => forms::text_modal(&serde_json::from_value::<TextForm>(args[0].clone()).unwrap()),
            "task_draft" => json!(forms::task_draft(string(0), &args[1])),
            "escape" => json!(render::escape(string(0))),
            "unslack" => json!(render::unslack(string(0))),
            "chunks" => json!(render::chunks(string(0), args[1].as_u64().unwrap() as usize)),
            "render_title" => json!(render::render_title(&args[0], string(1))),
            "render_status" => json!(render::render_status(&args[0], string(1))),
            "render_list" => json!(render::render_list(args[0].as_array().unwrap())),
            "notices" => json!(notices::notices(
                &args[0],
                &serde_json::from_value::<Vec<String>>(args[1].clone()).unwrap(),
                args[2].as_bool().unwrap()
            )),
            "render_notice" => json!(render::render_notice(
                &serde_json::from_value::<Notice>(args[0].clone()).unwrap(),
                args[1].as_bool().unwrap()
            )),
            "notice_blocks" => json!(render::notice_blocks(
                string(0),
                &serde_json::from_value::<AnswerPrompt>(args[1].clone()).unwrap()
            )),
            "render_resolved" => {
                json!(render::render_resolved((!args[0].is_null()).then_some(&args[0]), args[1].as_bool().unwrap()))
            }
            "offer_blocks" => {
                json!(render::offer_blocks(&serde_json::from_value::<AnswerOffer>(args[0].clone()).unwrap()))
            }
            "buttons_block" => render::buttons_block(&serde_json::from_value::<Vec<Button>>(args[0].clone()).unwrap()),
            "reply_blocks" => json!(render::reply_blocks(&serde_json::from_value::<Reply>(args[0].clone()).unwrap())),
            "option" => json!(render::option(string(0), string(1))),
            "parse_offer" => json!(render::parse_offer(string(0))),
            "parse_reference" => json!(render::parse_reference(string(0))),
            "parse_path" => json!(render::parse_path(string(0))),
            other => panic!("unknown golden function {other}"),
        };
        assert_eq!(result, case["expected"], "case {index}: {}", case["function"]);
    }
}
